INSERT INTO rules (num, title, text, sort) VALUES
('I',   'Знак не просят',        'Настоящий знак невозможно получить по собственной просьбе. Его можно только получить от действующего хранителя — незаметно, без слов и без свидетелей.', 1),
('II',  'Копий не существует',   'Каждый жетон вырезается вручную из дерева. Изготовление копий запрещено; ни один жетон не бывает полностью одинаковым.', 2),
('III', 'Обе сорок девятки',     'Перевёрнутая «49» — обязательная часть символа и никогда не изображается отдельно. Она есть отражение посвящённого мира, существующего рядом с обычным.', 3),
('IV',  'Жетон вместо имени',    'Во время закрытых собраний жетон предъявляется при входе вместо имени. Списки участников не ведутся; печати и документы упразднены.', 4),
('V',   'Следы времени священны','Трещины и сколы отражают историю владельцев и никогда не должны реставрироваться.', 5),
('VI',  'Один наследник',        'Каждое поколение семьи-хранителя выбирает лишь одного наследника, которому доверяется право однажды передать знак следующему человеку.', 6),
('VII', 'Молчание',              'Истинные знания передаются не через титулы, а через личный выбор достойного человека. О сказанном в капитуле не говорят за его пределами.', 7);
